import{_ as e,o as s,c as n,a3 as t}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"塔卫二天师府学院公告","description":"","frontmatter":{"translationSource":{"title":"塔卫二天师府学院公告","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}]]},"headers":[],"relativePath":"zh/talos-ii-tianshi-academy-announcements.md","filePath":"zh/page-SboV353S6KTHg6EWajOub8.md"}'),p={name:"zh/talos-ii-tianshi-academy-announcements.md"};function r(o,a,i,l,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t('<div class="logistics-content"><h1 id="塔卫二天师府学院公告" tabindex="-1">塔卫二天师府学院公告 <a class="header-anchor" href="#塔卫二天师府学院公告" aria-label="Permalink to &quot;塔卫二天师府学院公告&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-14. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>SboV353S6KTHg6EWajOub8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-rhEbMIPJZuRyzfIw3NG0TC"></span></p><h2 id="群公告文本" tabindex="-1">群公告文本 <a class="header-anchor" href="#群公告文本" aria-label="Permalink to &quot;群公告文本&quot;">​</a></h2><p><span class="mark-grey">*群公告文本应当控制内容为核心告知内容，确保文本量较少。</span></p><p>向群聊内寻求蓝图答疑前，请优先选择观看视频/阅读文档/查阅百科，文档链接：</p><p><a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a></p><p>如果没有问题的答案再寻求群友答疑。</p><p>寻求蓝图答疑请先展示以下物品的报表：<br> （可在报表中点击星标置顶物品方便展示）源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池（报表星标置顶）</p><p>我们不为答疑人员（群管理）以外的群友的回复担保；也请群友先了解，再质疑答疑人员。</p><p>原则上，提问前须先查视频/文档/游戏百科；已有答案的简单问题不要再问，只问资料中没有、表述不清或容易遗漏的内容。</p><p>群聊禁止敏感内容，违者踢出；禁止人身攻击，即使你被攻击过了，违者长时间禁言；不建议聊基建无关内容。有深造意愿、伸冤可私聊管理/群主。</p><p>群聊每周清人，保留管理与最近一周活跃。</p><p><span id="source-block-Jhl7Wbb9J03WQtic78XjeP"></span></p><h2 id="群管理条例" tabindex="-1">群管理条例 <a class="header-anchor" href="#群管理条例" aria-label="Permalink to &quot;群管理条例&quot;">​</a></h2><p><span class="mark-grey">*群管理条例应当清晰记录可能遇到的情况与相应的处罚方式，可以用特殊颜色字作为注释解释条例制定原因。</span></p><p>向群聊内寻求答疑时，鼓励先观看视频/阅读文档/查阅游戏内百科<span class="mark-grey">（据说可以有效提高答疑人员好感度）</span>视频链接包含在文档中故仅给出文档链接：<br> 1.5智能最大毛产-常见问题自查请往下翻，拓展功能...<br> 如果想进一步学习该基建原理，开发人员已将需要阅读的文档的链接贴在该文档中。尤其欢迎学习基建原理所产生的疑问。</p><p>向群聊内寻求答疑时，请一律展示以下物品<span class="mark-grey">，可以大幅提高问诊效率</span>：<br> （可在报表中点击星标置顶物品方便展示）源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池（默认排序 升序）<span class="mark-grey">（若不遵守容易引起答疑人员的反感甚至忽略）</span></p><p>群内禁止聊敏感内容，包括但不限于恐怖、血腥、擦边、金钱交易，一经发现直接踢出群聊。群内少聊无关内容，包括但不限于其他游戏、本家、抽卡、战斗排轴、邪道滑索，视情况予以禁言。</p><p>以答疑人员（即群管理<span class="mark-grey">，暂时不包括群主</span>）的回答为准<span class="mark-grey">（虽然答疑人员不一定绝对正确，但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员）</span>，也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</p><p>原则上我们不容许没有首先查阅视频/文档/游戏百科而发起的简单问题，在这些容易查看的信息源中对相当多常见问题都做了解答。<span class="mark-grey">提问这些问题对您来说或许不过是三两句话，但是对答疑人员来说大基数的人流反复提出同样的问题是巨大的精力乃至热情和善意的消耗，为了让答疑人员有足够的精力去解决更需要他们的疑难杂症，或忽略容易通过查阅视频/文档/游戏百科解决的问题——</span>当然此时或许会有除答疑外的热心群友的回答，但我们不负责这些回答的正确性。</p><p>不允许人身攻击，无论是新群友老群友答疑人员开发人员，任何人可以通过临时会话向群友和管理检举，一经发现将采取长时间禁言。<span class="mark-grey">请诸位传递知识和善意而不是戾气并对自己的言行负责。</span></p><p>为了尽可能保证答疑群有空位接纳新人新问题，每周不定期清理一周未发言的群友。如果有学习更多基建知识意愿，可以临时会话管理/群主以申请。</p><p>对答疑人员来说，不想答可以忽略，但是一旦选择回答就需要全程做到尊重对方的困境和疑问，对自己的答疑行为充分负责，当遇到无法解决的问题时应当明确后续跟进人选并清晰告知提问者后才能转交问题，忌发泄情绪忌半途而废。如果该过程中双方有存在违规，任何人包括当事人可以向管理/群主检举，忌当面对质。</p><p><span id="source-block-vA7Yq3jYQxo0dEbUqY38XY"></span></p><h2 id="群管理记录" tabindex="-1">群管理记录 <a class="header-anchor" href="#群管理记录" aria-label="Permalink to &quot;群管理记录&quot;">​</a></h2><p><span class="mark-grey">*群管理记录包含两类。对受罚情况记录应当记录受处罚情况，包括所在群聊，受罚者，大体内容，对应到的管理条例（较容易判定的可以不记录），受罚等级。对群清理记录应当记录提醒时间，执行者，执行时间；群清理不一定要记录。</span></p></div>',1)])])}const b=e(p,[["render",r]]);export{u as __pageData,b as default};
